            '【隔热与恒温互斥】"完全隔热封闭空间"与"温度恒为T"相互矛盾，两者只能取其一。隔热意味着Q=0，系统做功必然改变温度；若要维持恒温则必须允许与热源的热交换',
            '【理想气体绝热性质】理想气体绝热过程中温度必然改变（γ>1），不可设定"绝热且等温"。绝热膨胀必降温，绝热压缩必升温，这是热力学第一定律的直接推论',
            '【卡诺效率温标要求】卡诺循环效率η=1-T_冷/T_热，T必须用热力学温标（开尔文），不得用摄氏度代入。例如T_冷=27°C=300K, T_热=127°C=400K，η=1-300/400=25%，而非1-27/127',
            '【熵的状态函数性质vs宇宙熵增】熵是状态函数，循环过程ΔS_系统=0恒成立（不论可逆不可逆），但不可逆循环中ΔS_宇宙=ΔS_系统+ΔS_环境>0——ΔS_环境=-Q_不可逆/T_环境不等于零。两个概念必须清晰区分',
            '【范德华临界参数自洽】范德华气体的临界参数：T_c=8a/(27Rb), V_c=3nb, p_c=a/(27b²)，三者由a、b唯一确定。题目中若同时给出a、b和临界参数的任意两个，必须验证第三个是否自洽；不得随意设定互相矛盾的临界参数',
            '【热力学第二定律方向性】自发过程总熵增ΔS_宇宙≥0（等号仅对可逆过程成立），热量不可能自发从低温物体传到高温物体——题目中不得设计违背第二定律方向性的物理场景（如"隔热系统中热量自发从冷端流向热端"）',
            '【热容与过程路径相关性】热容C=δQ/dT是过程量而非状态量——等压热容C_p≠等容热容C_v，且C_p-C_v=nR（理想气体）或C_p-C_v=TVα²/κ_T（一般体系）。不得在绝热过程中使用C_p或C_v计算热量（绝热过程Q=0）',
            '【焦耳-汤姆逊效应正负性】焦耳-汤姆逊系数μ_JT=(∂T/∂p)_H可正可负——理想气体μ_JT=0（焦耳-汤姆逊效应恰好为零）；实际气体在反转温度T_i以下μ_JT>0（节流降温），T_i以上μ_JT<0（节流升温）。氢气/氦气的T_i很低（分别约202K/40K），常温下节流升温而非降温——题目中节流效应的温度变化方向必须与气体种类和工作温度匹配',
            '【克拉珀龙方程的适用条件】dp/dT=ΔS/(ΔV)=L/(TΔV)适用于一级相变（如固液、液气、固气），其中L是相变潜热，ΔV是相变体积差。对于二级相变（连续相变，如超导转变、铁磁-顺磁转变），潜热L=0且ΔV=0，克拉珀龙方程退化为0/0形式，必须用埃伦费斯特方程代替',
            '【热力学函数的自然变量】内能U的自然变量是(S,V)，焓H的自然变量是(S,p)，亥姆霍兹自由能F的自然变量是(T,V)，吉布斯自由能G的自然变量是(T,p)。用非自然变量表达热力学势时必须通过勒让德变换——不得随意混用，如"在等温等压条件下系统平衡态由F=U-TS最小确定"是错误的（应由G最小确定）',
            '【多元系统自由度计算】吉布斯相律f=C-P+2（C为组分数，P为相数），对于封闭系统。开放系统或有约束条件（如化学平衡、电中性条件）时f=C-P+2-R（R为独立约束数）。纯水三相点f=1-3+2=0（不变点），但若含溶质则f增加——题目中的自由度数必须与组分、相数、约束条件完全自洽',
            '【不可逆过程熵变计算方法】不可逆过程的系统熵变不能用δQ/T积分直接计算（因为dS≥δQ/T中等号仅对可逆过程成立）。正确方法是：设计一条连接相同初末态的可逆路径，沿该路径计算∫δQ_rev/T。环境的熵变可直接用ΔS_环境=-Q_实际/T_环境（环境通常视为热源，其内部过程可逆）'
