            pressure_range: '压强必须≥0（负压无物理意义，但拉伸液体中亚稳态可短暂出现负压）。常见量级：标准大气压~10⁵Pa，超高真空~10⁻⁸Pa，金刚石压腔~10¹¹Pa——题目中给定的压强必须与实验装置能力匹配',
            heat_capacity_ratio: '理想气体比热比γ=C_p/C_v：单原子γ=5/3≈1.667，双原子(刚性)γ=7/5=1.4，双原子(含振动,高温)γ≈9/7≈1.286，多原子~1.1-1.3——γ必须>1（因C_p>C_v恒成立），且与声称的气体种类自洽',
            van_der_waals_parameters: '范德华参数a和b的物理约束：a>0（分子间吸引力），b>0（分子有限体积），且V>nb（实际可占据体积不能小于分子共体积）。常见气体：N₂的a=0.141 Pa·m⁶/mol², b=3.91×10⁻⁵ m³/mol；CO₂的a=0.365, b=4.27×10⁻⁵——题目中的a、b值必须量级合理',
