            latent_heat_sign: '相变潜热的符号约定：吸热为正（固→液→气方向），放热为负。水的汽化潜热L_v≈2260kJ/kg(100°C)，熔化潜热L_m≈334kJ/kg(0°C)——题目中潜热值必须与相变方向一致，且数值在正确量级',
            thermal_conductivity: '导热系数κ的量级：金属~10-400 W/(m·K)（铜~400，铁~80），绝热材料~0.01-0.1，气体~0.01-0.05，水~0.6——题目中的热传导问题必须使用与材料匹配的κ值'
