            '【衰变能量学约束】α衰变要求Q_α>0（母核质量>子核+He-4质量）；β⁻要求M_母>M_子（原子质量）；β⁺要求M_母>M_子+2m_e；电子俘获要求M_母>M_子。不满足能量条件的衰变模式物理上禁戒',
