// 主题识别函数（优先匹配最长关键词，避免通用短词抢占具体方向）
export function identifyDiscipline(topic: string): string {
    let bestKey = 'mechanics-classical';
    let bestLen = 0;

    for (const [key, discipline] of Object.entries(PHYSICS_DISCIPLINES)) {
        for (const keyword of discipline.keywords) {
            if (topic.includes(keyword) && keyword.length > bestLen) {
                bestLen = keyword.length;
                bestKey = key;
            }
        }
    }
    return bestKey;
}

// V2 方向分组：将 27 个细粒度方向映射到 19 个 V2 合并组
const V2_DIRECTION_GROUPS: Record<string, string[]> = {
    'quantum': ['modern-quantum'],
    'mechanics': ['mechanics-classical', 'mechanics-dynamics', 'mechanics-fluid'],
    'electromagnetism': ['electromagnetism-static', 'electromagnetism-dynamic', 'electromagnetism-circuit'],
    'thermodynamics': ['thermodynamics-laws'],
    'stat-physics': ['stat-classical', 'stat-quantum', 'stat-phase-transition'],
    'optics': ['optics-wave', 'optics-geometric'],
    'relativity': ['modern-relativity'],
    'nuclear': ['modern-nuclear'],
    'condensed-crystal': ['condensed-crystal'],
    'condensed-band': ['condensed-band'],
    'condensed-magnetic': ['condensed-magnetic'],
    'radiation': ['electrodynamics-radiation'],
    'waveguide': ['electrodynamics-waveguide'],
    'relativistic-ed': ['electrodynamics-relativistic'],
    'mathphys-special': ['mathphys-special-functions'],
    'mathphys-pde': ['mathphys-pde'],
    'mathphys-complex': ['mathphys-complex'],
    'amo-atomic-spectra': ['amo-atomic-spectra'],
    'amo-laser': ['amo-laser'],
    'plasma-basic': ['plasma-basic'],
    'plasma-wave': ['plasma-wave'],
};

export function identifyV2Group(topic: string): string {
    const key = identifyDiscipline(topic);
    for (const [group, keys] of Object.entries(V2_DIRECTION_GROUPS)) {
        if (keys.includes(key)) return group;
    }
    return 'mechanics';
}

export function getV2Strategies(topic: string, maxItems: number = 3): string {
    const key = identifyDiscipline(topic);
    const group = identifyV2Group(topic);
    const groupKeys = V2_DIRECTION_GROUPS[group] || [];

    const primary = (PHYSICS_DISCIPLINES as any)[key]?.v2_strategies || [];
    const result = [...primary];
    for (const k of groupKeys) {
        if (k !== key) {
            const extra = (PHYSICS_DISCIPLINES as any)[k]?.v2_strategies || [];
            result.push(...extra);
        }
    }
    const selected = result.slice(0, maxItems);
    if (selected.length === 0) return '';
    return selected.join('\n\n');
}

export function getV2Constraints(topic: string): string {
    const key = identifyDiscipline(topic);
    const group = identifyV2Group(topic);
    const groupKeys = V2_DIRECTION_GROUPS[group] || [];

    const allConstraints: string[] = [];
    for (const k of groupKeys) {
        const c = (PHYSICS_DISCIPLINES as any)[k]?.v2_constraints || [];
        allConstraints.push(...c);
    }
    if (allConstraints.length === 0) return '';
    const name = (PHYSICS_DISCIPLINES as any)[key]?.name || '物理';
    return `【${name}命题专项约束（强制执行）】：\n` +
        allConstraints.map((c: string, i: number) => `${i + 1}. ${c}`).join('\n');
}

// 获取学科特定的难度指导 (始终强制最高难度)
export function getDisciplineGuidance(topic: string): string {
    const disciplineKey = identifyDiscipline(topic);
    const discipline = PHYSICS_DISCIPLINES[disciplineKey as keyof typeof PHYSICS_DISCIPLINES];
    const peakGuidance = (discipline as any).peak_difficulty;
    const forbiddenErrors: string[] | undefined = (discipline as any).forbidden_errors;
    const paramConstraints: Record<string, string> | undefined = (discipline as any).parameter_constraints;
    const antiPatternStrategies: string[] | undefined = (discipline as any).anti_pattern_strategies;

    const forbiddenSection = forbiddenErrors && forbiddenErrors.length > 0
        ? `\n【该方向已知高频错误——严格禁止（每条必须自查）】：\n${forbiddenErrors.map((e, i) => `${i + 1}. ❌ ${e}`).join('\n')}\n`
        : '';

    const paramSection = paramConstraints
        ? `\n【参数约束自检清单——生成数值前逐条核对】：\n${Object.entries(paramConstraints).map(([key, desc]) => `• ${key}: ${desc}`).join('\n')}\n`
        : '';

    const antiPatternSection = antiPatternStrategies && antiPatternStrategies.length > 0
        ? `\n【反模式匹配策略——至少执行其中2条以增加题目区分度】：\n${antiPatternStrategies.map((s, i) => `${i + 1}. ${s}`).join('\n')}\n`
        : '';

    return `
【学科背景识别】：${discipline.name}
【该主题的顶级考核深度】：
${peakGuidance}
${forbiddenSection}${paramSection}${antiPatternSection}
【核心生成法则（极度重要）】：
- 你的核心任务是**完全围绕用户输入的具体主题："${topic}"** 来进行命题！
- 上方的"考核深度"展示了该领域下题目必须达到的**思维复杂度**（如涉及多体耦合、非线性方程、矢量场积分等）。
- 绝不要出那种"只需带入一个通用公式就能解出"的初级题目。必须考察极其深刻的底层物理图像！
- 例如：如果主题是"牛顿第二定律"，你必须考核含约束力、非惯性系或变力的复杂动力学分析。
- 只要题目逻辑死死扣住 "${topic}" 并且深度达到上述"顶级考核深度"，请完全发挥你的创造力。
- 题目背景应在：实验室科研、工程应用、前沿学术研究、纯理论推导中随机切换（由系统指令指定）。
`;
}
